#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minOperationsMaxProfit(vector<int>& customers, int boardingCost, int runningCost) {
        int waiting = 0, boarded = 0, max_profit = 0, best_rotations = -1;
        int rotations = 0, i = 0, n = customers.size();
        while (i < n || waiting > 0) {
            if (i < n) {
                waiting += customers[i++];
            }
            int board = min(4, waiting);
            waiting -= board;
            boarded += board;
            rotations++;
            int profit = boarded * boardingCost - rotations * runningCost;
            if (profit > max_profit) {
                max_profit = profit;
                best_rotations = rotations;
            }
        }
        return best_rotations;
    }
};

class Solution {
    public int minOperationsMaxProfit(int[] customers, int boardingCost, int runningCost) {
        int waiting = 0, boarded = 0, maxProfit = 0, bestRotations = -1;
        int rotations = 0, i = 0, n = customers.length;
        while (i < n || waiting > 0) {
            if (i < n) {
                waiting += customers[i++];
            }
            int board = Math.min(4, waiting);
            waiting -= board;
            boarded += board;
            rotations++;
            int profit = boarded * boardingCost - rotations * runningCost;
            if (profit > maxProfit) {
                maxProfit = profit;
                bestRotations = rotations;
            }
        }
        return bestRotations;
    }
}

